const $=(s,p=document)=>p.querySelector(s),$$=(s,p=document)=>[...p.querySelectorAll(s)];const state={hero:0,cart:Number(localStorage.getItem('heartkong-cart')||0)};const toast=message=>{const el=$('.toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2200)};$('.cart-button b').textContent=state.cart;addEventListener('scroll',()=>$('.header').classList.toggle('scrolled',scrollY>20));$('.menu-toggle').addEventListener('click',e=>{const open=e.currentTarget.getAttribute('aria-expanded')==='true';e.currentTarget.setAttribute('aria-expanded',String(!open));$('.nav').classList.toggle('open',!open)});$$('.nav a').forEach(a=>a.addEventListener('click',()=>{$('.nav').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false')}));
const slides=$$('.hero-slide'),dots=$('.hero-dots');slides.forEach((_,i)=>{const b=document.createElement('button');b.type='button';b.setAttribute('aria-label',`${i+1}번 슬라이드`);b.addEventListener('click',()=>showHero(i));dots.append(b)});function showHero(index){state.hero=(index+slides.length)%slides.length;slides.forEach((s,i)=>s.classList.toggle('active',i===state.hero));$$('button',dots).forEach((d,i)=>d.classList.toggle('active',i===state.hero));$('.hero-count').textContent=`${String(state.hero+1).padStart(2,'0')} / ${String(slides.length).padStart(2,'0')}`}$('.hero-prev').addEventListener('click',()=>showHero(state.hero-1));$('.hero-next').addEventListener('click',()=>showHero(state.hero+1));showHero(0);let heroTimer=setInterval(()=>showHero(state.hero+1),6500);$('.hero').addEventListener('mouseenter',()=>clearInterval(heroTimer));
const productTrack=$('.product-track');$('.product-arrow.prev').addEventListener('click',()=>productTrack.scrollBy({left:-productTrack.clientWidth*.72,behavior:'smooth'}));$('.product-arrow.next').addEventListener('click',()=>productTrack.scrollBy({left:productTrack.clientWidth*.72,behavior:'smooth'}));$$('.add-cart').forEach(button=>button.addEventListener('click',()=>{state.cart++;localStorage.setItem('heartkong-cart',state.cart);$('.cart-button b').textContent=state.cart;toast(`${button.dataset.product}을 장바구니에 담았어요 ♥`)}));
const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.12});$$('.reveal').forEach(el=>observer.observe(el));const modalMap={login:$('#login-modal'),signup:$('#signup-modal'),admin:$('#admin-modal')};function openModal(name){Object.values(modalMap).forEach(m=>m.open&&m.close());modalMap[name].showModal();document.body.classList.add('locked')}$$('[data-open]').forEach(b=>b.addEventListener('click',()=>openModal(b.dataset.open)));$$('.modal-close,.admin-exit').forEach(b=>b.addEventListener('click',()=>{b.closest('dialog').close();document.body.classList.remove('locked')}));$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){d.close();document.body.classList.remove('locked')}}));$$('[data-auth]').forEach(form=>form.addEventListener('submit',e=>{if(window.HEARTKONG_FIREBASE_CONFIG?.apiKey)return;e.preventDefault();const data=new FormData(form),mode=form.dataset.auth,email=data.get('email');localStorage.setItem('heartkong-demo-user',JSON.stringify({email,name:data.get('name')||'하트콩 회원'}));form.closest('dialog').close();document.body.classList.remove('locked');toast(mode==='signup'?'회원가입 데모가 완료됐어요 ♥':`${email}님, 반가워요 ♥`)}));$$('[data-admin-tab]').forEach(b=>b.addEventListener('click',()=>{$$('[data-admin-tab]').forEach(x=>x.classList.remove('active'));b.classList.add('active');if(b.dataset.adminTab!=='dashboard')toast(`${b.textContent}은 Firebase MCP 연결 후 실시간으로 표시됩니다.`)}));if(window.HEARTKONG_FIREBASE_CONFIG?.apiKey){$$('.firebase-status').forEach(el=>el.textContent='Firebase 연결됨')}
